SELECT 
FROM tb_complaint_article a
LEFT JOIN tb_complaint_category c ON c.category_id = a.category_id
WHERE a.complaint_master_id = #{complaintMasterId}
  AND a.delete_yn = 'N'

  AND a.category_id = #{categoryId}


  AND a.status = #{status}


  AND a.writer_name LIKE CONCAT('%',#{writerName},'%')


  AND a.complaint_no LIKE CONCAT('%',#{complaintNo},'%')


  AND (a.title LIKE CONCAT('%',#{keyword},'%')
    OR a.complaint_no LIKE CONCAT('%',#{keyword},'%'))

ORDER BY a.created_at DESC
LIMIT #{pageSize} OFFSET #{offset}

